String shopText(
  String key,
  String language, [
  Map<String, Object> values = const {},
]) {
  var text =
      shopTranslations[AppLanguageController.resolveCode(language)]![shopKeys
          .indexOf(key)];
  for (final e in values.entries) {
    text = text.replaceAll('{${e.key}}', '${e.value}');
  }
  return text;
}

